INSERT INTO readings
    (id, user_id, title, content, language, created_at, origin, editorial_level, category)
VALUES
    ('20000000-0000-0000-0000-000000000001', NULL,
     'The Lost Blue Scarf',
     $$Nora has a blue scarf. Her grandmother made it for her, so Nora wears it every cold morning. One Monday, she walks to the bakery with her brother Leo. They buy warm bread and two small cakes. When they leave the shop, Nora cannot find her scarf. She looks under the table and beside the door. Leo asks the baker, but he has not seen it. They walk back along the street. A bus stops, children cross the road, and a woman opens a flower shop. Then Leo points at a little brown dog. The dog is sitting near a bench with something blue under its paws. Nora calls softly. The dog moves, and there is the scarf. Its owner smiles and gives it back. Nora is happy, but the scarf is wet and dirty. At home, she washes it and puts it by the window. The next morning it is clean again. Nora decides to hold it carefully whenever she visits the bakery.$$,
     'en', CURRENT_TIMESTAMP, 'PLATFORM', 'A1', 'Daily Life'),
    ('20000000-0000-0000-0000-000000000002', NULL,
     'The Sparrow and the Red Cup',
     $$A sparrow lives in a garden behind a small house. Every day, it drinks from a red cup near the kitchen door. The cup is old, but it always has fresh water. One hot afternoon, the sparrow sees a young rabbit in the garden. The rabbit is tired and cannot find the pond. The sparrow flies to the red cup and sings. The rabbit follows the sound, but the cup is too high for it. The sparrow tries to push the cup. It is heavy. A mouse comes from under a box and helps. Together they move the cup to the edge of the step. Some water falls onto the ground. The rabbit drinks from the little pool and feels strong again. The next day, the woman in the house sees the empty cup. She puts a wide bowl beside it. Now birds, mice, and rabbits can all drink there. The sparrow learns that a small place can become better when friends share an idea and work together.$$,
     'en', CURRENT_TIMESTAMP, 'PLATFORM', 'A1', 'Animals'),
    ('20000000-0000-0000-0000-000000000003', NULL,
     'A Boat for the Little Island',
     $$Sam lives near a quiet lake. In the middle of the lake there is a little island with one tall tree. Sam often looks at it from the shore. One sunny day, his aunt brings a small yellow boat. She gives Sam a life jacket and shows him how to use the oars. They enter the boat together. At first, Sam moves one oar too fast, and the boat turns in a circle. He laughs and tries again. Soon they travel straight across the blue water. Near the island, they notice three ducks and a nest among the grass. They stop far away so the birds are safe. On the other side of the island, Sam finds a wooden sign on the ground. He lifts it and reads, Keep the lake clean. Sam and his aunt collect two empty bottles from the shore. They take them home in the boat. The island is small, but the trip feels like a great adventure. Sam decides to return and care for the peaceful place.$$,
     'en', CURRENT_TIMESTAMP, 'PLATFORM', 'A1', 'Adventure'),
    ('20000000-0000-0000-0000-000000000004', NULL,
     'The Garden Behind the School',
     $$Lina is new at school. She knows her teacher, but she does not know the other children. At lunch, she sits alone near a wall. A boy named Tom sees a leaf in her hair. He smiles and says there is a garden behind the school. Lina follows him through a green gate. The garden has beans, tomatoes, flowers, and a small apple tree. Three students are watering the plants. Tom gives Lina a yellow watering can. She helps a girl called Ava with the dry flowers. Ava asks Lina about her old town, and Lina tells her about the large park near her former home. After lunch, the children make signs for the plants. Lina draws a bright red tomato on one sign. On Friday, the class picks vegetables and makes a salad. Lina brings apples from home. Everyone shares the food at a long table. The garden is not only a place for plants. It is also the first place where Lina feels that she belongs to her new school.$$,
     'en', CURRENT_TIMESTAMP, 'PLATFORM', 'A1', 'Friendship'),

    ('20000000-0000-0000-0000-000000000005', NULL,
     'The Train to Harbor Town',
     $$Eli had never traveled alone before, so he checked his ticket three times before leaving home. His train was going to Harbor Town, where his cousin Maya lived. At the station, a helpful worker showed him the right platform. Eli found a window seat and placed his bag above it. When the train moved, apartment buildings slowly disappeared and green fields filled the view. An older passenger told him about a stone bridge they would cross before the coast. Eli almost missed it because he was looking at a map. Later, the train stopped unexpectedly beside a farm. The driver explained that sheep were standing near the track. Everyone laughed when a farmer and his dog guided them away. Although the delay was short, Eli worried that Maya would leave the station. Instead, she was waiting beside a clock with a handmade sign. They walked to the harbor, ate soup, and watched fishing boats return. Eli noticed that traveling alone required attention, but it also gave him confidence. On the journey home, he helped another passenger find the correct platform.$$,
     'en', CURRENT_TIMESTAMP, 'PLATFORM', 'A2', 'Travel'),
    ('20000000-0000-0000-0000-000000000006', NULL,
     'A Quiet Morning by the River',
     $$Before sunrise, Priya and her father carried a basket to the river. They wanted to count birds for a community nature project. The path was still dark, and drops of water covered the grass. When they reached the river, they sat quietly under a willow tree. At first, Priya heard only moving water. Then a kingfisher flew low across the surface, bright as a blue light. Her father wrote its name in a notebook. They noticed ducks, two herons, and several small birds among the reeds. Priya wanted to move closer, but her father asked her to wait because sudden movement could frighten them. After an hour, they found plastic cups near the path. They put the rubbish in their basket instead of leaving it for another person. On the way home, heavy rain began, so they waited beneath an old bridge. Priya was cold and wet, yet she was pleased with their list. That evening, she sent the results to the project leader. The information would help the community understand how the river changed during the year.$$,
     'en', CURRENT_TIMESTAMP, 'PLATFORM', 'A2', 'Nature'),
    ('20000000-0000-0000-0000-000000000007', NULL,
     'The Light in Room Twelve',
     $$Marta worked at a small hotel during the summer. One evening, she noticed a light in room twelve after the last guest had checked out. She asked her manager, but he said the room was empty and locked. They climbed the stairs together. Before they reached the door, the light went off. Marta heard a soft sound inside, like paper moving across a table. The manager opened the door carefully. No person was there. The bed was tidy, the window was closed, and the lamp was cold. However, a white envelope lay on the floor. It had the name Rosa on it. Rosa was the cook, and she had lost that envelope in the room a week earlier. It contained an old photograph of her parents. A cleaning fan had pushed the envelope from behind a cabinet, while a loose branch outside had touched the light switch through a narrow window gap. The mystery had an ordinary reason, but Rosa was delighted to recover her picture. Marta decided that noticing small details was useful, even when they first appeared strange.$$,
     'en', CURRENT_TIMESTAMP, 'PLATFORM', 'A2', 'Mystery'),
    ('20000000-0000-0000-0000-000000000008', NULL,
     'Lunch for the Night Team',
     $$Jon worked in a busy hospital kitchen. His team prepared meals for patients during the day, but the nurses on the night shift often found only cold snacks. Jon wanted to improve this situation. He spoke to his supervisor and offered to prepare a simple soup before he went home. The supervisor agreed because the ingredients were already available. On Monday, Jon made vegetable soup and left clear instructions beside the pot. When the night team arrived, they sent him a short thank-you message. The next day, another cook provided fresh bread. Soon, everyone began sharing ideas. One person prepared fruit cups, while another changed the schedule so hot food stayed safe. The plan did not increase costs, but it required attention and good communication. After a month, the kitchen asked the nurses which meals were most useful. Jon discovered that small changes could support people who worked at different hours. Instead of deciding everything alone, he invited both teams to a meeting, and together they created a better weekly menu.$$,
     'en', CURRENT_TIMESTAMP, 'PLATFORM', 'A2', 'Work'),

    ('20000000-0000-0000-0000-000000000009', NULL,
     'The Phone-Free Table',
     $$At first, the phone-free table was only a joke. During lunch, everyone in Lena's office placed a phone beside a large plant, and the first person who reached for a screen had to make tea. The habit began because colleagues had noticed that their conversations were becoming shorter. Even when people sat together, messages divided their attention. During the first week, the table felt unusually quiet. Then Amir described a repair project at home, and two coworkers offered useful advice. Another day, Lena learned that the new designer had studied in the same coastal town as her sister. These details had never appeared in their work chats. The experiment did not make technology an enemy. The team still used shared calendars and online documents to improve their work. However, they began to decide which moments required a device and which required a person. After a month, nobody needed the tea rule. Some employees joined the table only once a week, while others came daily. A visitor questioned whether the rule excluded urgent family messages, so the team added a simple exception and avoided turning a useful habit into a strict performance. Productivity did not suddenly transform, but people asked for help earlier and solved minor problems before they grew. A playful challenge had provided an opportunity to rebuild an ordinary form of trust.$$,
     'en', CURRENT_TIMESTAMP, 'PLATFORM', 'B1', 'Technology'),
    ('20000000-0000-0000-0000-000000000010', NULL,
     'The Empty Lot Project',
     $$For years, an empty lot divided two streets in Mateo's neighborhood. Weeds covered broken bricks, and people avoided the area after dark. When the city invited residents to suggest improvements, Mateo proposed a community garden. Some neighbors supported the idea; others believed it would create more work than value. Instead of arguing, the group organized a weekend cleanup as a small test. Families removed rubbish, students painted the wall, and an experienced gardener explained which plants could survive the dry summer. The change was immediate, although the larger challenge had only begun. Water was expensive, and volunteers could not visit every day. The group collected rainwater from a nearby community center and created a schedule. They also provided two raised beds for older residents who found it difficult to bend down. A local cafe agreed to save coffee grounds for compost, while children built signs asking visitors to protect young plants. By autumn, the lot produced herbs, beans, and more conversation than anyone expected. Not every problem disappeared. Tools sometimes went missing, and decisions about shared space remained complicated. Yet residents had discovered a practical reason to cooperate. The garden improved the environment, but its most valuable harvest was a stronger sense of responsibility for the neighborhood.$$,
     'en', CURRENT_TIMESTAMP, 'PLATFORM', 'B1', 'Community'),
    ('20000000-0000-0000-0000-000000000011', NULL,
     'Learning to Ask Better Questions',
     $$Nadia joined a bicycle repair workshop because she wanted a practical skill. On the first evening, the instructor showed the class a damaged wheel and asked what they noticed. Nadia immediately suggested replacing it. Instead, the instructor encouraged everyone to examine the spokes, rim, and tire. A loose spoke had caused the wheel to bend, so a small adjustment solved the problem. Nadia realized that she often searched for answers before understanding the question. At work, she began applying the same habit. When customers reported an error, she asked when it appeared, what had changed, and whether other people had experienced it. Her conversations became longer at first, but the team avoided unnecessary repairs. She also felt less embarrassed when she did not know something. Asking a precise question was not proof of ignorance; it was a method for learning. The habit required patience because some questions produced no quick answer. Still, recording what the team had tested prevented them from repeating the same failed ideas. Several months later, a new colleague struggled with a confusing task. Nadia resisted the desire to provide an immediate solution. She asked him to describe each step and helped him notice the missing detail. The workshop had taught her more than bicycle maintenance. It had changed how she approached uncertainty and how she supported other learners.$$,
     'en', CURRENT_TIMESTAMP, 'PLATFORM', 'B1', 'Education'),
    ('20000000-0000-0000-0000-000000000012', NULL,
     'The Road Beyond Pine Hill',
     $$When Daniel received an opportunity to manage a small mountain hostel, he could not decide whether to accept it. His city job was stable, and his friends lived nearby. The hostel, however, belonged to an uncle who planned to retire. Daniel visited Pine Hill before making a choice. The road climbed through forest and ended beside a wooden building with twelve rooms. On his first morning, a storm blocked the electricity. Guests gathered around the fireplace while Daniel searched for lamps and prepared breakfast on a gas stove. Instead of complaining, several people helped. A teacher organized games for the children, and a traveler showed Daniel how to reset the old water pump. By evening, the storm had passed. Daniel stood outside and noticed lights returning across the valley. He understood that hostel work would provide less routine and more responsibility. It would also connect him with different people and unexpected challenges. His uncle showed him the accounts, explained the quiet winter season, and warned that beautiful views did not guarantee a successful business. Back in the city, Daniel listed practical risks rather than imagining only success or failure. Finally, he agreed to manage the hostel for one year. The decision did not remove his doubts, but it turned them into questions he could answer through experience.$$,
     'en', CURRENT_TIMESTAMP, 'PLATFORM', 'B1', 'Travel'),

    ('20000000-0000-0000-0000-000000000013', NULL,
     'The Cost of Constant Attention',
     $$Every morning, Inez opened her news feed before opening the curtains. The habit seemed harmless: a quick way to understand what had happened overnight. Yet the quick check expanded. One headline led to a video, which led to a debate, and twenty minutes disappeared before breakfast. At work, notifications continued to divide her attention into increasingly narrow pieces. She was busy throughout the day but struggled to explain what she had completed. Inez did not want to abandon technology, because digital tools provided genuine opportunities for connection and learning. Instead, she conducted a personal experiment. She removed alerts that required no immediate action, moved social applications away from the home screen, and reserved two periods for messages. The first days were uncomfortable. Silence felt like missing information. Gradually, however, she noticed the impulse to check without automatically obeying it. Her concentration improved, although the most surprising change occurred outside work. Conversations felt less hurried, and waiting in a queue became an occasion to observe rather than consume. A colleague tried the same method and failed because his role required rapid replies. Together they designed a shared channel for genuine emergencies, demonstrating that attention policies must reflect different responsibilities rather than impose one ideal routine. The experiment also revealed a wider problem: many services compete by increasing time spent, not by improving the value of that time. Individual habits matter, but designers and institutions also shape the environment in which attention is exercised. Inez kept her phone; what changed was the assumption that every signal deserved an immediate response.$$,
     'en', CURRENT_TIMESTAMP, 'PLATFORM', 'B2', 'Technology'),
    ('20000000-0000-0000-0000-000000000014', NULL,
     'A Market Changes Its Rhythm',
     $$The Saturday market had occupied the central square for generations. Farmers arrived before dawn, families bought bread, and musicians played beside the fountain. When rents increased and younger residents began ordering groceries online, several stalls closed. Some traders blamed technology, while others argued that the market had failed to change. The town council proposed replacing half the stalls with parking spaces, promising easier access and higher sales. The plan divided the community. Leila, whose family sold cheese there, feared that reducing the market would accelerate its decline. However, she also knew that nostalgia alone could not protect it. She invited traders, residents, and delivery cyclists to test a different model. Customers could order basic goods online during the week and collect them on Saturday, when producers offered tastings, workshops, and seasonal products. Older traders received help photographing their goods, and a shared delivery route served customers who could not travel. The first months were uneven. Online orders remained modest, and coordinating forty independent businesses created conflict. A vegetable seller worried that shared advertising favored attractive luxury products, so the group published transparent sales figures and rotated featured stalls. They also created a low-cost table where surplus food was offered late in the afternoon instead of being discarded. Nevertheless, foot traffic increased because the market became both convenient and social. The solution did not restore an imagined past. Instead, it allowed an old institution to change its rhythm without losing its purpose: connecting local producers with the people who depended on them.$$,
     'en', CURRENT_TIMESTAMP, 'PLATFORM', 'B2', 'Society'),
    ('20000000-0000-0000-0000-000000000015', NULL,
     'Listening to the Forest at Night',
     $$A research team entered the cloud forest carrying devices that looked like small black boxes. Their goal was not to capture animals but to record the sounds of the environment. Traditional surveys required scientists to identify species during brief visits, which meant that rare or nocturnal animals were easily missed. The recorders could listen for months. Each morning, software compared thousands of calls, clicks, and rustles with known patterns. The technology increased the amount of evidence, but it did not remove the need for human judgment. Rain could resemble insect activity, and a bird might produce a call not yet included in the database. Local guides often noticed these mistakes because they understood seasonal changes that the model ignored. One night, a guide named Celso heard a low repeated whistle. The software classified it as wind, yet Celso believed it came from a frog that had not been observed locally for decades. The team placed additional recorders near a stream and later confirmed his suspicion. Before announcing the result, they invited independent specialists to review the recordings and avoided revealing the exact location, since publicity could attract collectors. The discovery did not prove that the forest was healthy; a single species could survive while the wider habitat declined. It did, however, provide a reason to protect the stream and improve future monitoring. The recordings also showed quieter dawn periods near newly constructed roads, giving researchers a measurable question for the next survey. By combining patient observation, community experience, and computational analysis, the project turned sound into a detailed account of an ecosystem under pressure.$$,
     'en', CURRENT_TIMESTAMP, 'PLATFORM', 'B2', 'Science'),
    ('20000000-0000-0000-0000-000000000016', NULL,
     'The Key Beneath the Floor',
     $$On the third night in the old coastal house, Mara heard a measured knock beneath her bedroom floor. The building belonged to her absent grandfather, who had left instructions that nobody should enter the locked room upstairs. Mara dismissed the sound as pipes until it returned at exactly two in the morning. Her cousin Julian suggested opening the floorboards, although neither of them had permission to damage the house. Instead, they waited downstairs during the next high tide. The knock emerged again, this time from inside a wall. Following it through the corridor, they discovered that seawater pushed air along an abandoned heating pipe. Behind a loose panel lay a narrow brass key. It fitted the forbidden room. Inside, they expected money or family secrets, but found shelves of notebooks describing changes in the coastline. Their grandfather had recorded storms, damaged dunes, and disappearing bird nests for forty years. Photographs were labeled with dates and tide levels, while hand-drawn maps showed a beach narrowing year after year. A final note explained that he had locked the room to protect the records during repairs, then forgotten where the key had fallen. Mara and Julian faced a decision. Selling the house would be easier, yet the notebooks could provide valuable evidence for a conservation study. They contacted a local university but required the originals to remain accessible to the village rather than disappear into a private archive. By morning, the mysterious knocking had become ordinary physics, while the apparently ordinary house had become an archive they were unwilling to lose.$$,
     'en', CURRENT_TIMESTAMP, 'PLATFORM', 'B2', 'Mystery'),

    ('20000000-0000-0000-0000-000000000017', NULL,
     'The Museum of Unfinished Things',
     $$The museum occupied a former railway warehouse and displayed objects that had never fulfilled their intended purpose. There was a clock without hands, a bridge model rejected by city planners, and an elegant chair too fragile to support anyone. Visitors initially treated the collection as a catalogue of failure. They laughed at impractical machines and photographed the most spectacular mistakes. Yet the curator, Dr. Vale, had designed the exhibition around a subtler argument: unfinished work exposes decisions that successful objects conceal. Beside each item, notebooks revealed compromises, abandoned alternatives, and changes in circumstance. A medical device had become obsolete before approval, although its sensor later improved farming equipment. The bridge model had inspired a safer design in another country. Even the fragile chair had led its maker to discover a new method for bending wood. During a public discussion, a student asked whether the museum romanticized failure. Dr. Vale admitted that not every mistake produces wisdom; some merely waste resources or harm people. Reflection, evidence, and accountability are what transform an unsuccessful attempt into knowledge. Another visitor questioned whose unfinished objects were preserved. Domestic tools and community experiments rarely entered institutional archives, partly because their creators lacked formal records. The museum responded by inviting residents to document abandoned local projects, including the reasons they ended. This addition complicated the exhibition: failure could result from unequal funding and political neglect, not only flawed imagination. After the discussion, the student returned to the clock without hands. Its inventor had wanted people to experience time as light and shadow rather than numbers, but the mechanism never worked reliably. The object remained useless as a clock. Nevertheless, it offered a precise question about usefulness itself: must an invention solve the problem it began with, or can its value emerge from the possibilities it leaves behind?$$,
     'en', CURRENT_TIMESTAMP, 'PLATFORM', 'C1', 'Culture'),
    ('20000000-0000-0000-0000-000000000018', NULL,
     'A City That Predicts Its Citizens',
     $$The municipal platform promised to anticipate public needs. By combining transport records, service requests, and environmental sensors, it could identify neighborhoods likely to experience flooding, overcrowded buses, or shortages of medical appointments. The early results were impressive. Repairs occurred sooner, emergency routes improved, and limited resources reached some residents before they submitted a complaint. However, prediction gradually shifted from assistance to influence. Officials used behavioral profiles to decide which messages citizens received and which inspections businesses faced. Although each decision appeared efficient in isolation, the system offered no clear way to challenge an inaccurate profile. Samira, an analyst on the project, discovered that residents of an old industrial district were repeatedly classified as unlikely to participate in cultural programs. Funding therefore moved elsewhere, confirming the very pattern the model predicted. She argued that prediction was being mistaken for destiny. Her colleagues responded that removing the model would restore slower and more arbitrary decisions. A public meeting exposed another complication. Residents wanted transparency, but publishing detailed models could reveal private patterns or enable powerful organizations to manipulate scores. Samira proposed a different approach: publish the factors behind high-impact recommendations, allow communities to correct local data, commission independent audits, and measure whether interventions expanded opportunity rather than merely reproduced past behavior. Temporary pilot decisions would expire unless evidence justified renewing them. The debate revealed that ethical technology is rarely a choice between calculation and ignorance. The deeper question is who can inspect, contest, and redefine the categories through which a city understands its citizens. Efficiency may improve public life, but only accountability prevents a helpful forecast from becoming an invisible command.$$,
     'en', CURRENT_TIMESTAMP, 'PLATFORM', 'C1', 'Technology'),
    ('20000000-0000-0000-0000-000000000019', NULL,
     'The Language of the Evening Square',
     $$At dusk, the square belonged to several versions of the city at once. Elderly men unfolded wooden boards for a game learned in another country. Teenagers rehearsed dance routines beside a statue whose history few of them knew. Restaurant workers exchanged jokes across languages, while tourists searched for an authentic experience that could be photographed before dinner. Cultural officials planned to renovate the square and make its identity more coherent. Their proposal included uniform signs, organized performance areas, and a historical route marked in bronze. The design was attractive, yet some residents worried that coherence would silence the informal practices that had given the place meaning. Mei, an architect raised nearby, conducted interviews instead of beginning with drawings. She discovered that disagreement was not evidence of a community without identity; it was part of how identity was continually negotiated. Shopkeepers wanted clear delivery access, musicians valued unpredictable audiences, parents needed safe space, and recent migrants sought somewhere they could gather without purchasing anything. During a trial closure, officials observed that removing traffic made the square safer but displaced delivery workers into a neighboring street. The revised schedule therefore changed by hour instead of imposing a permanent boundary. Mei designed flexible zones rather than fixed ones. Benches could become small stages, vehicle barriers could be moved, and historical markers included questions as well as official explanations. A council of rotating residents reviewed festivals so established organizations did not control every desirable date. The renovated square did not resolve every conflict. Noise, commerce, memory, and belonging still competed. Its success lay elsewhere: it provided enough structure for different groups to remain visible to one another. A living culture, Mei concluded, is not a polished story inherited intact, but an ongoing conversation about who has the right to shape shared space.$$,
     'en', CURRENT_TIMESTAMP, 'PLATFORM', 'C1', 'Society'),
    ('20000000-0000-0000-0000-000000000020', NULL,
     'The Cartographer of Vanishing Roads',
     $$By the time Elian reached the northern valley, three roads on his official map no longer existed. One had collapsed into the river, another ended at a locked quarry, and the third was remembered only by villagers who described it as if recalling a deceased relative. Elian had been commissioned to produce a definitive regional map before a new railway altered the landscape. He trusted instruments, coordinates, and measurable distance. The villagers, however, offered routes defined by weather, memory, and obligation: the path used when the river froze, the trail to a ruined chapel, the long descent taken by families during an evacuation decades earlier. These accounts contradicted one another, yet each contained a form of accuracy his survey could not express. An old teacher named Sera challenged his purpose. A definitive map, she argued, might grant official reality to some roads while erasing others a second time. Elian initially dismissed the concern as sentiment. Then railway engineers selected a construction route through an orchard because his preliminary map represented the land as empty. The farmer produced no formal deed, only tax receipts and generations of testimony. Elian understood that technical absence could have material consequences. He revised his method. Alongside elevation and distance, he recorded seasonal access, local names, disputed boundaries, and oral histories, clearly distinguishing evidence from interpretation. Draft pages were returned to villages for correction, although Elian retained disagreements rather than forcing a convenient consensus. The finished atlas was less certain than the document his employer had requested, but more truthful about the valley. On its final page, Elian left a deliberate blank around a rumored mountain passage. It was not an admission of careless work. It acknowledged that responsible knowledge sometimes requires preserving uncertainty until someone can travel the road.$$,
     'en', CURRENT_TIMESTAMP, 'PLATFORM', 'C1', 'History');
